;     ld a, e
;     out (#99), a
;     nop
;     ld a, d
;     or #40
;     out (#99), a
;     nop
;     ld a, b
;     out (#98), a
;     pop bc
;     inc hl
;     inc de
;     dec bc
;     ld a, b
;     or c
;     jp nz, .resource_dzx0_vram_copy_loop
;     pop af
;     pop hl
;     ex (sp), hl
;     add a, a
;     jp nc, .resource_dzx0_vram_literals
; .resource_dzx0_vram_new_offset:
