;     rl c
;     rl b
;     jp .resource_dzx0_vram_elias_loop
;
; ; ------------------------------------------------------------------
; ; resource_load_to_ram_by_id
; ; Inputs:
; ;   A  = resource id
; ;   DE = destination in RAM
; ; Outputs:
; ;   carry clear on success
; ;   carry set if resource id is missing
; ; Clobbers:
