    ld hl, SM_Exit_Door_Gem_Gate_state_exit_hidden_1775000000012 + 1      ; HL = &OnEnter Actions Ptr field
    ld e, (hl)
    inc hl
    ld d, (hl)                    ; DE = OnEnter Actions Ptr
    ld a, 2                ; A = entity index
    call call_SM_ExecuteActions_resident

    ret
