; Data labels are emitted in bank4 section (org #C000) for megarom builds.

; Register Contract:
;   Purpose: Wait a configurable number of frames after showing the presentation screen.
;   Inputs:
;     - B = frame count
;   Outputs:
;     - None
;   Clobbers:
;     - AF
;     - B
;   Preserved:
;     - BC
;     - DE
;     - HL
;     - IX
;     - IY

; Register Contract:
;   Purpose: Wait for SPACE press and release after showing the presentation screen.
;   Inputs:
;     - None
;   Outputs:
;     - None
;   Clobbers:
;     - AF
;   Preserved:
;     - BC
;     - DE
;     - HL
;     - IX
;     - IY
presentation_wait_for_fire:
.pwff_wait_press:
    halt
    call presentation_read_fire_direct
    or a
    jr z, .pwff_wait_press
.pwff_wait_release:
    halt
    call presentation_read_fire_direct
    or a
    jr nz, .pwff_wait_release
    ret

; Register Contract:
;   Purpose: Read SPACE directly for presentation-screen waits without depending on runtime input tasks.
;   Inputs:
;     - None
;   Outputs:
;     - A = 1 if SPACE pressed, A = 0 otherwise
;   Clobbers:
;     - AF
;   Preserved:
;     - BC
;     - DE
;     - HL
;     - IX
;     - IY
;   Notes:
;     - Uses keyboard matrix row 8 bit 0 (SPACE, active low).
presentation_read_fire_direct:
    ld a, 8
    call FAST_SNSMAT
    bit 0, a
    jr z, .prfd_pressed
    xor a
    ret
.prfd_pressed:
    ld a, 1
    ret

; Register Contract:
;   Purpose: Show the imported fullscreen presentation image in SCREEN 2 without waiting for input.
;   Inputs:
;     - None
;   Outputs:
;     - None
;   Clobbers:
;     - AF
;     - BC
;     - DE
;     - HL
;   Preserved:
;     - IX
;     - IY
;   Notes:
;     - Loads pattern/color banks 0..2 and the 32x24 name table.
;     - MegaROM GameFlow uses this short entrypoint so waits happen after the far-call bank is restored.
show_presentation_screen_image:
    call DISSCR
    ld a, 2
    call CHGMOD
    ; Fullscreen presentation replaces shared gameplay/font tables in VRAM.
    call resource_invalidate_gameplay_vram_cache
    call call_clear_all_sprites_resident
    call call_update_sprites_to_vram_resident
    ld a, RESOURCE_ID_PRESENTATION_SCREEN_PATTERNS_B0
    ld de, CHRTBL2
    call resource_load_to_vram_by_id

    ld a, RESOURCE_ID_PRESENTATION_SCREEN_PATTERNS_B1
    ld de, CHRTBL2 + #800
    call resource_load_to_vram_by_id

    ld a, RESOURCE_ID_PRESENTATION_SCREEN_PATTERNS_B2
    ld de, CHRTBL2 + #1000
    call resource_load_to_vram_by_id

    ld a, RESOURCE_ID_PRESENTATION_SCREEN_COLORS_B0
    ld de, CLRTBL2
    call resource_load_to_vram_by_id

    ld a, RESOURCE_ID_PRESENTATION_SCREEN_COLORS_B1
    ld de, CLRTBL2 + #800
    call resource_load_to_vram_by_id

    ld a, RESOURCE_ID_PRESENTATION_SCREEN_COLORS_B2
    ld de, CLRTBL2 + #1000
    call resource_load_to_vram_by_id

    ld a, RESOURCE_ID_PRESENTATION_SCREEN_NAMETBL
    ld de, NAMETBL
    call resource_load_to_vram_by_id

    call ENASCR
    ret

; Register Contract:
;   Purpose: Show the imported fullscreen presentation image and apply its configured wait behavior.
;   Inputs:
;     - None
;   Outputs:
;     - None
;   Clobbers:
;     - AF
;     - BC
;     - DE
;     - HL
;   Preserved:
;     - IX
;     - IY
;   Notes:
;     - Legacy entrypoint for direct callers; GameFlow MegaROM handles waits from its own resident-safe path.
show_presentation_screen:
    call show_presentation_screen_image
    call presentation_wait_for_fire
    ret

; [SCREEN LOADING FUNCTIONS moved to screen_loaders far module]


; --- End of Far Bank 14 — pad to 8KB boundary ---
BANK_14_USED_END:
    ds #8000 - $, #FF
    org FAR_BANK_14_ROM_START + #2000

; ##################################################################
; FAR BANK 15 — [#6000h-#8000h] FAR CODE: animtiles
; Accessed ONLY via trampolines in bank 0 (entrypoint_far labels).
; At runtime: bank0 saves P1, maps bank15 to P1,
; calls routine, then restores P1.
; NOTE: routines in this bank MUST only call code in bank 0 or
;       primary banks (1-2). No far-to-far calls allowed.
; ##################################################################
FAR_BANK_15_ROM_START:

    org #6000

; @mideas:block id=runtime.animtiles.core kind=routine owner=animtiles roots=init_animated_tiles,update_animated_tiles,update_animated_tiles_vram,anim_upload_char_frame,set_animation_speed,register_animated_tile,get_tile_animation_frame
; ==================================================================
; ANIMATED TILES SYSTEM
; File: animtiles.asm
; Description: Background tile animation for water, lava, fire, etc.
; ==================================================================

; Auto-detected animated groups:
;   frame groups: 5
;   transform groups: 2

; ==================================================================
; ANIMATED TILES CONSTANTS
; ==================================================================

; Animation speeds (in frames)
ANIM_SPEED_SLOW         EQU 15      ; ~250ms (water)
ANIM_SPEED_MEDIUM       EQU 8       ; ~133ms (lava)
ANIM_SPEED_FAST         EQU 4       ; ~66ms (fire)

; Maximum animated tiles
MAX_ANIM_TILES          EQU 5
ANIM_TILE_ENTRY_SIZE    EQU 7       ; char, chars, frames, speed, bytesPerFrame, ptr(2)
ANIM_TRANS_ENTRY_SIZE   EQU 4       ; char, chars, opCode, flags
ANIM_TILE_DATA_BANK     EQU 0       ; Deprecated: anim data is local to animtiles code bank

; ==================================================================
; ANIMATED TILES INITIALIZATION
; ==================================================================

init_animated_tiles:
    ; Initialize animation variables
    xor a
    ld (anim_tile_timer), a
    ld (anim_tile_frame), a

    ; Set default global animation speed
    ld a, 8
    ld (anim_tile_speed), a

    ; Upload initial animation frame state immediately
    call call_update_animated_tiles_vram_resident

    ret

; ==================================================================
; ANIMATED TILES UPDATE FUNCTIONS
; ==================================================================

; ------------------------------------------------------------------
; update_animated_tiles
; Update animation frame and redraw animated tiles if needed
; Call this every frame from main loop
; ------------------------------------------------------------------
update_animated_tiles:
    ; Skip animation work on screens with no animated tile groups
    ld a, (current_screen_anim_group_count)
    or a
    ret z

    ; Increment timer
    ld a, (anim_tile_timer)
    inc a
    ld (anim_tile_timer), a

    ; Check if it's time to advance frame
    ld b, a
    ld a, (anim_tile_speed)
    or a
    jr nz, .anim_speed_ok
    ld a, 1
    ld (anim_tile_speed), a
.anim_speed_ok:
    cp b
    ret nc                          ; Not yet time to update (timer < speed)

    ; Reset timer
    xor a
    ld (anim_tile_timer), a

    ; Advance global animation counter
    ld a, (anim_tile_frame)
    inc a
    ld (anim_tile_frame), a

    ; Update all animated tiles in VRAM
    call call_update_animated_tiles_vram_resident

    ret

; ------------------------------------------------------------------
; update_animated_tiles_vram
; Update pattern data in VRAM for all animated tiles
; This updates the actual tile patterns based on current frame
; Destroys: AF, BC, DE, HL
; ------------------------------------------------------------------
update_animated_tiles_vram:
    ; Protect VDP port sequence from ISR VRAM writes.
    ; Always re-enables on exit (see FAST_LDIRVM note on LD A,I bug).
    di
    ld hl, anim_tile_table

.anim_vram_loop:
    ld a, (hl)                      ; A = target char code
    cp 255
    jp z, .anim_vram_done

    push af                         ; Save target char code
    inc hl
    ld a, (hl)                      ; A = chars per tile
    push af
    inc hl
    ld b, (hl)                      ; B = frame count
    inc hl
    inc hl                          ; Skip speed byte (reserved)
    ld c, (hl)                      ; C = bytes per frame
    inc hl
    ld e, (hl)                      ; DE = data pointer
    inc hl
    ld d, (hl)
    inc hl                          ; HL = next table entry
    push hl
    ex de, hl                       ; HL = data pointer

    ; frame = global_frame % frame_count
    ; Fast path for power-of-two frame counts: frame & (count-1)
    ld a, b
    dec a
    ld d, a
    and b
    jr nz, .anim_mod_slow
    ld a, (anim_tile_frame)
    and d
    jr .anim_mod_done
.anim_mod_slow:
    ld a, (anim_tile_frame)
.anim_mod_loop:
    cp b
    jr c, .anim_mod_done
    sub b
    jr .anim_mod_loop
.anim_mod_done:

    ; DE = frame offset (frame * bytes_per_frame)
    ld b, a
    ld d, 0
    ld e, 0
.anim_mul_loop:
    ld a, b
    or a
    jr z, .anim_mul_done
    ld a, e
    add a, c
    ld e, a
    ld a, d
    adc a, 0
    ld d, a
    dec b
    jr .anim_mul_loop
.anim_mul_done:
    add hl, de                      ; HL = frame data pointer

    pop de                          ; DE = next table entry pointer
    pop af
    ld b, a                         ; B = chars per tile
    pop af
    ld c, a                         ; C = target char code
    push de

.anim_char_loop:
    ld a, b
    or a
    jr z, .anim_char_done

    push bc
    push hl
    ld a, c
    call anim_upload_char_frame
    pop hl
    pop bc

    ld de, 16
    add hl, de                      ; Next char frame chunk
    inc c                           ; Next target char code
    dec b
    jr .anim_char_loop

.anim_char_done:
    pop de
    ex de, hl                       ; HL = next table entry
    jp .anim_vram_loop

.anim_vram_done:

    ei
    ret

; ------------------------------------------------------------------
; set_animation_speed
; Set global animation speed for all animated tiles
; Input:  A = Speed (frames between updates)
; ------------------------------------------------------------------
set_animation_speed:
    or a
    jr nz, .anim_speed_store
    ld a, 1
.anim_speed_store:
    ld (anim_tile_speed), a
    ret

; ------------------------------------------------------------------
; anim_copy_8_bytes
; Copy 8 bytes from CPU memory to VRAM
; Input: DE = source pointer, HL = VRAM destination
; Destroys: AF, BC, DE, HL
; ------------------------------------------------------------------
anim_copy_8_bytes:
    push de                         ; Save source pointer
    push hl                         ; Save VRAM destination
    pop de                          ; DE = VRAM destination for FAST_LDIRVM
    pop hl                          ; HL = source pointer for FAST_LDIRVM
    ld bc, 8
    call FAST_LDIRVM
    push hl
    pop de                          ; Preserve legacy postcondition: DE = source + 8
    ret

; ==================================================================
; anim_upload_char_frame
; Upload one animated char (pattern + color) to all 3 Screen 2 banks
; Input: A = target char code, HL = source frame chunk (16 bytes)
; Source layout: 8 pattern bytes + 8 color bytes
; Destroys: AF, BC, DE, HL
; ==================================================================
anim_upload_char_frame:
    push af
    push bc
    push de
    push hl

    ; BC = target char offset (charCode * 8)
    ld l, a
    ld h, 0
    add hl, hl
    add hl, hl
    add hl, hl
    ld b, h
    ld c, l

    pop hl
    ex de, hl                      ; DE = source pattern pointer

    ; Pattern bank 0
    push de
    ld hl, CHRTBL2
    add hl, bc
    push bc
    call anim_copy_8_bytes
    pop bc
    pop de

    ; Pattern bank 1
    push de
    ld hl, CHRTBL2 + #800
    add hl, bc
    push bc
    call anim_copy_8_bytes
    pop bc
    pop de

    ; Pattern bank 2
    ld hl, CHRTBL2 + #1000
    add hl, bc
    push bc
    call anim_copy_8_bytes
    pop bc

    ; DE now points to color bytes (source + 8)
    ; Color bank 0
    push de
    ld hl, CLRTBL2
    add hl, bc
    push bc
    call anim_copy_8_bytes
    pop bc
    pop de

    ; Color bank 1
    push de
    ld hl, CLRTBL2 + #800
    add hl, bc
    push bc
    call anim_copy_8_bytes
    pop bc
    pop de

    ; Color bank 2
    ld hl, CLRTBL2 + #1000
    add hl, bc
    push bc
    call anim_copy_8_bytes
    pop bc

    pop de
    pop bc
    pop af
    ret

