; ------------------------------------------------------------------
; register_animated_tile
; Runtime registration is not supported in this generator version.
; Input:  A = Tile ID to animate
;         B = Number of frames (2-4)
;         C = Animation speed
; Output: A = 0 if failed (table full), 1 if success
; Destroys: AF, DE, HL
; ------------------------------------------------------------------
register_animated_tile:
    xor a                           ; Not supported (static generated table)
    ret

; ------------------------------------------------------------------
; get_tile_animation_frame
; Get current animation frame for a tile
; Input:  A = target char code
; Output: A = Current frame index (mod numFrames), or 0 if not animated
; Destroys: BC, DE, HL
; ------------------------------------------------------------------
get_tile_animation_frame:
    ld c, a                         ; C = char code to search
    ld hl, anim_tile_table

.anim_search_loop:
    ld a, (hl)
    cp 255
    jr z, .anim_not_found
    cp c
    jr z, .anim_found_tile

    ld de, ANIM_TILE_ENTRY_SIZE
    add hl, de
    jr .anim_search_loop

.anim_found_tile:
    inc hl
    inc hl
    ld b, (hl)                      ; B = numFrames
    ld a, (anim_tile_frame)
.anim_found_mod:
    cp b
    jr c, .anim_found_done
    sub b
    jr .anim_found_mod
.anim_found_done:
    ret

.anim_not_found:
    xor a
    ret

; ==================================================================
; END OF ANIMATED TILES SYSTEM
; ==================================================================
; @mideas:endblock id=runtime.animtiles.core


; --- End of Far Bank 15 — pad to 8KB boundary ---
BANK_15_USED_END:
    ds #8000 - $, #FF
    org FAR_BANK_15_ROM_START + #2000

; ##################################################################
; FAR BANK 16 — [#6000h-#8000h] FAR CODE: hud
; Accessed ONLY via trampolines in bank 0 (entrypoint_far labels).
; At runtime: bank0 saves P1, maps bank16 to P1,
; calls routine, then restores P1.
; NOTE: routines in this bank MUST only call code in bank 0 or
;       primary banks (1-2). No far-to-far calls allowed.
; ##################################################################
FAR_BANK_16_ROM_START:

    org #6000

; @mideas:block id=runtime.hud.core kind=routine owner=hud roots=init_hud,render_hud,force_render_hud,imprimir_marco,hud_draw_frame
; ==================================================================
; HUD SYSTEM - Screen 2 Text Rendering
; ==================================================================
; Total HUD Elements: 5
; Screens with HUD: 1
;
; HUD Elements use TileBank fonts to render text in Screen 2 mode
; Each element can be positioned anywhere on screen (256x192 pixels)
; ==================================================================

; ------------------------------------------------------------------
; HUD DATA STRUCTURES
; ------------------------------------------------------------------

HUD_ELEMENT_COUNT   EQU 5

; HUD Element Data Table
; Format: [Type:1][X:1][Y:1][Width:1][Height:1][Flags:1][TextPtr:2][Visible:1]
hud_element_data:
    DB 1, 0, 8    ; Element 0: Score at (0,8)
    DB 11, 1, 0 ; W, H, Flags
    DW hud_text_0             ; Text pointer
    DB 1                ; Visible
    DB 3, 104, 8    ; Element 1: Lives at (104,8)
    DB 1, 1, 0 ; W, H, Flags
    DW hud_text_1             ; Text pointer
    DB 1                ; Visible
    DB 6, 192, 8    ; Element 2: SceneName at (192,8)
    DB 7, 1, 0 ; W, H, Flags
    DW hud_text_2             ; Text pointer
    DB 1                ; Visible
    DB 14, 128, 8    ; Element 3: CustomCounter at (128,8)
    DB 2, 1, 0 ; W, H, Flags
    DW hud_text_3             ; Text pointer
    DB 1                ; Visible
    DB 14, 160, 8    ; Element 4: CustomCounter at (160,8)
    DB 2, 1, 0 ; W, H, Flags
    DW hud_text_4             ; Text pointer
    DB 1                ; Visible

; HUD Text Strings
hud_text_0:
    DB "SCORE 00000", 0
hud_text_1:
    DB "3", 0
hud_text_2:
    DB "STAGE 1", 0
hud_text_3:
    DB "00", 0
hud_text_4:
    DB "00", 0

; ------------------------------------------------------------------
; imprimir_marco
; Draw HUD frame borders (called once per screen load)
; ------------------------------------------------------------------
imprimir_marco:
    push af
    push bc
    push de
    push hl
    push ix

    ld b, HUD_ELEMENT_COUNT
    ld ix, hud_element_data

.marco_loop:
    push bc                     ; Save counter

    ; Check visible flag first (offset 8)
    ld a, (ix+8)                ; A = Visible
    or a
    jr z, .skip_marco           ; Skip if not visible

    ; Read element fields
    ld d, (ix+1)                ; D = X position (pixels)
    ld e, (ix+2)                ; E = Y position (pixels)
    ld b, (ix+3)                ; B = Width (tiles)
    ld c, (ix+4)                ; C = Height (tiles)
    ld a, (ix+5)                ; A = Flags

    ; Check if border flag is set (bit 0)
    bit 0, a
    jr z, .skip_marco           ; Skip if no border

    ; Convert X,Y pixels to Tile coordinates
    ; TileX = X/8, TileY = Y/8
    ld a, d
    srl a
    srl a
    srl a
    ld d, a                     ; D = Tile X

    ld a, e
    srl a
    srl a
    srl a
    ld e, a                     ; E = Tile Y

    ; Adjust for padding: Frame is 1 tile larger on all sides
    dec d                       ; Frame X = Content X - 1
    dec e                       ; Frame Y = Content Y - 1

    ; Frame Width = Content Width + 2
    inc b
    inc b                       ; Width += 2

    inc c
    inc c                       ; Height += 2

    call hud_draw_frame

.skip_marco:
    ; Move to next element
    ld bc, 9                    ; Size of each element entry
    add ix, bc                  ; IX points to next element

    pop bc                      ; Restore counter
    djnz .marco_loop

    pop ix
    pop hl
    pop de
    pop bc
    pop af
    ret

; ------------------------------------------------------------------
; render_hud
; Main HUD rendering function
; Only redraws when hud_dirty_flag is set
; Input:
;   None
; Output:
;   None
; Clobbers:
;   None visible to caller
; Preserves:
;   AF, BC, DE, HL, IX
; Notes:
;   - Returns immediately if hud_dirty_flag = 0
;   - Re-applies dynamic numeric fields (Score/Lives/custom bindings) after redrawing static text
; ------------------------------------------------------------------
render_hud:
    ld a, (hud_dirty_flag)
    or a
    ret z                       ; Skip if HUD hasn't changed
    xor a
    ld (hud_dirty_flag), a      ; Clear flag after rendering
    push af
    push bc
    push de
    push hl
    push ix

    ld b, HUD_ELEMENT_COUNT
    ld ix, hud_element_data

.render_loop:
    push bc                     ; Save counter

    ; Check visible flag first (offset 8)
    ld a, (ix+8)                ; A = Visible
    or a
    jp z, .skip_element         ; Skip if not visible

    ; Read element fields
    ld d, (ix+1)                ; D = X position (pixels)
    ld e, (ix+2)                ; E = Y position (pixels)
    ld b, (ix+3)                ; B = Width (tiles)
    ld c, (ix+4)                ; C = Height (tiles)
    ld a, (ix+5)                ; A = Flags

    ; Save values we'll need later
    push bc                     ; Save Width, Height
    push de                     ; Save X, Y

    ; ---------------------------------------------------------
    ; 1. Draw Frame (if enabled)
    ; ---------------------------------------------------------
    bit 0, a                    ; Check Bit 0 (Border)
    jr z, .no_border

    ; Convert X,Y pixels to Tile coordinates
    ; TileX = X/8, TileY = Y/8
    ld a, d
    srl a
    srl a
    srl a
    ld d, a                     ; D = Tile X
    
    ld a, e
    srl a
    srl a
    srl a
    ld e, a                     ; E = Tile Y
    
    ; Adjust for padding: Frame is 1 tile larger on all sides
    dec d                       ; Frame X = Content X - 1
    dec e                       ; Frame Y = Content Y - 1
    
    ; Frame Width = Content Width + 2
    inc b
    inc b                       ; Width += 2
    
    inc c
    inc c                       ; Height += 2
    
    call hud_draw_frame
    
    ; Restore original X, Y, Width, Height for text rendering
    pop de                      ; DE = X, Y (pixels)
    pop bc                      ; BC = Width, Height (tiles)
    ; Re-push in same order as original (BC bottom, DE top)
    push bc                     ; Save Width, Height (bottom)
    push de                     ; Save X, Y (top)

.no_border:
    ; ---------------------------------------------------------
    ; 2. Draw Text
    ; ---------------------------------------------------------
    pop de                      ; DE = X, Y (pixels)
    pop bc                      ; BC = Width, Height (discard, not needed)

    ; Calculate VRAM address from X,Y pixel coordinates
    ; Screen 2 Name Table = #1800 + (Y/8)*32 + (X/8)
    
    ; Y/8 = row
    ld a, e                     ; A = Y
    srl a
    srl a
    srl a                       ; A = Y/8 (row)

    ; row * 32
    ld l, a
    ld h, 0
    add hl, hl                  ; * 2
    add hl, hl                  ; * 4
    add hl, hl                  ; * 8
    add hl, hl                  ; * 16
    add hl, hl                  ; * 32

    ; Add X/8
    ld a, d                     ; A = X
    srl a
    srl a
    srl a                       ; A = X/8 (column)
    ld e, a
    ld d, 0
    add hl, de

    ; Add Name Table base
    ld de, #1800
    add hl, de                  ; HL = VRAM address

    ; Get Text Pointer
    ld e, (ix+6)                ; TextPtr Low
    ld d, (ix+7)                ; TextPtr High
    ; DE = Text Pointer

    ; Render text string at HL (VRAM) from DE (string)
    call hud_print_string

.skip_element:
    ; Move to next element
    ld bc, 9                    ; Size of each element entry
    add ix, bc                  ; IX points to next element

    pop bc                      ; Restore counter
    djnz .render_loop

    ; Re-apply dynamic Score digits after redrawing static HUD text.
    ld a, (global_var_score)
    ld l, a
    ld a, (global_var_score+1)
    ld h, a
    call update_hud_score

    ; Re-apply dynamic Lives digit after redrawing static HUD text.
    ld a, (global_var_lives)
    call update_hud_lives

    ; Re-apply HUD-bound numeric field 3 from global_var_time_remaining.
    ld a, (global_var_time_remaining)
    ld l, a
    ld a, (global_var_time_remaining+1)
    ld h, a
    call update_hud_dynamic_3

    ; Re-apply HUD-bound numeric field 4 from global_var_gems.
    ld a, (global_var_gems)
    ld l, a
    ld h, 0
    call update_hud_dynamic_4


    pop ix
    pop hl
    pop de
    pop bc
    pop af
    ret

; ------------------------------------------------------------------
; force_render_hud
; Force a HUD redraw on this frame, preserving caller-visible registers
; Input:
;   None
; Output:
;   None
; Clobbers:
;   None visible to caller
; Preserves:
;   AF, BC, DE, HL, IX
; Notes:
;   - Sets hud_dirty_flag = 1 and then calls render_hud
; ------------------------------------------------------------------
force_render_hud:
    push af
    ld a, 1
    ld (hud_dirty_flag), a
    call call_render_hud_resident
    pop af
    ret

; ------------------------------------------------------------------
; hud_print_string
; Print a null-terminated string to Screen 2 Name Table
; Input: HL = VRAM address, DE = String pointer (RAM)
; ------------------------------------------------------------------
hud_print_string:
    push af
    push bc
    push de
    push hl

.print_loop:
    ld a, (de)                  ; Get character from string
    or a                        ; Check for null terminator
    jr z, .print_done

    cp 32                       ; Check if >= 32 (printable ASCII)
    jr nc, .valid_char
    ld a, 32                    ; Replace control chars with space
.valid_char:
    push de
    call FAST_WRTVRM
    pop de
    inc de
    inc hl
    jr .print_loop

.print_done:
    pop hl
    pop de
    pop bc
    pop af
    ret

; ------------------------------------------------------------------
; hud_ascii_to_tile
; Convert ASCII character to tile index for font rendering
; Input: A = ASCII character
; Output: A = Tile index (ASCII code for direct mapping)
; ------------------------------------------------------------------
hud_ascii_to_tile:
    cp 32
    ret nc
    ld a, 32
    ret

; ------------------------------------------------------------------
; hud_draw_frame
; Draw a rectangular frame using font characters
; Input: D = Tile X, E = Tile Y, B = Width (tiles), C = Height (tiles)
; Uses characters: 43 (+), 45 (-), 124 (|)
; ------------------------------------------------------------------
hud_draw_frame:
    push af
    push bc
    push de
    push hl
    ld l, e
    ld h, 0
    add hl, hl
    add hl, hl
    add hl, hl
    add hl, hl
    add hl, hl
    ld e, d
    ld d, 0
    add hl, de
    ld de, #1800
    add hl, de
    push hl
    push bc
    ld a, 43
    call FAST_WRTVRM
    inc hl
    ld a, b
    sub 2
    jr z, .skip_top_edge
    jr c, .skip_top_edge
    ld b, a
.top_edge_loop:
    ld a, 45
    call FAST_WRTVRM
    inc hl
    djnz .top_edge_loop
.skip_top_edge:
    ld a, 43
    call FAST_WRTVRM
    pop bc
    pop hl
    ld de, 32
    add hl, de
    ld a, c
    sub 2
    jr z, .bottom_row
    jr c, .bottom_row
    ld c, a
.middle_row_loop:
    push hl
    push bc
    ld a, 124
    call FAST_WRTVRM
    ld a, b
    dec a
    ld e, a
    ld d, 0
    add hl, de
    ld a, 124
    call FAST_WRTVRM
    pop bc
    pop hl
    ld de, 32
    add hl, de
    dec c
    jr nz, .middle_row_loop
.bottom_row:
    ld a, 43
    call FAST_WRTVRM
    inc hl
    ld a, b
    sub 2
    jr z, .skip_bottom_edge
    jr c, .skip_bottom_edge
    ld b, a
.bottom_edge_loop:
    ld a, 45
    call FAST_WRTVRM
    inc hl
    djnz .bottom_edge_loop
.skip_bottom_edge:
    ld a, 43
    call FAST_WRTVRM
    pop hl
    pop de
    pop bc
    pop af
    ret

; ------------------------------------------------------------------
; update_hud_score
; Update score HUD element with current score value
; Input: HL = Score value (16-bit binary, 0-65535)
; Output:
;   None
; Clobbers:
;   None visible to caller
; Preserves:
;   AF, BC, DE, HL
; ------------------------------------------------------------------
update_hud_score:
    push af
    push bc
    push de
    push hl

    ld de, #1826

    ; Runtime digit 0: / 10000
    ld bc, 10000
    call hud_div16
    add a, '0'
    push hl
    ld h, d
    ld l, e
    call FAST_WRTVRM
    pop hl
    inc de
    ; Runtime digit 1: / 1000
    ld bc, 1000
    call hud_div16
    add a, '0'
    push hl
    ld h, d
    ld l, e
    call FAST_WRTVRM
    pop hl
    inc de
    ; Runtime digit 2: / 100
    ld bc, 100
    call hud_div16
    add a, '0'
    push hl
    ld h, d
    ld l, e
    call FAST_WRTVRM
    pop hl
    inc de
    ; Runtime digit 3: / 10
    ld bc, 10
    call hud_div16
    add a, '0'
    push hl
    ld h, d
    ld l, e
    call FAST_WRTVRM
    pop hl
    inc de
    ; Final digit: ones (remainder)
    ld a, l
    add a, '0'
    push hl
    ld h, d
    ld l, e
    call FAST_WRTVRM
    pop hl
    pop hl
    pop de
    pop bc
    pop af
    ret

; Helper: HL = HL / BC, A = quotient, HL = remainder
hud_div16:
    xor a
.hud_div16_loop:
    or a
    sbc hl, bc
    jr c, .hud_div16_done
    inc a
    jr .hud_div16_loop
.hud_div16_done:
    add hl, bc
    ret

; ------------------------------------------------------------------
; update_hud_lives
; Update lives HUD element
; Input: A = Number of lives (0-9)
; Output:
;   None
; Clobbers:
;   None visible to caller
; Preserves:
;   AF, HL
; ------------------------------------------------------------------
update_hud_lives:
    push af
    push hl
    add a, '0'
    ld hl, #182D
    call FAST_WRTVRM
    pop hl
    pop af
    ret

; ------------------------------------------------------------------
; update_hud_dynamic_3
; Update HUD-bound numeric field 3 from HL value
; Input: HL = Current value (16-bit binary, 0-65535)
; Output:
;   None
; Clobbers:
;   None visible to caller
; Preserves:
;   AF, BC, DE, HL
; Notes:
;   - Writes only the numeric digits in VRAM; the static label is not touched
; ------------------------------------------------------------------
update_hud_dynamic_3:
    push af
    push bc
    push de
    push hl

    ld de, #1830

    ; Runtime digit 0: / 10
    ld bc, 10
    call hud_div16
    add a, '0'
    push hl
    ld h, d
    ld l, e
    call FAST_WRTVRM
    pop hl
    inc de
    ; Final digit: ones (remainder)
    ld a, l
    add a, '0'
    push hl
    ld h, d
    ld l, e
    call FAST_WRTVRM
    pop hl
    pop hl
    pop de
    pop bc
    pop af
    ret

; ------------------------------------------------------------------
; update_hud_dynamic_4
; Update HUD-bound numeric field 4 from HL value
; Input: HL = Current value (16-bit binary, 0-65535)
; Output:
;   None
; Clobbers:
;   None visible to caller
; Preserves:
;   AF, BC, DE, HL
; Notes:
;   - Writes only the numeric digits in VRAM; the static label is not touched
; ------------------------------------------------------------------
update_hud_dynamic_4:
    push af
    push bc
    push de
    push hl

    ld de, #1834

    ; Runtime digit 0: / 10
    ld bc, 10
    call hud_div16
    add a, '0'
    push hl
    ld h, d
    ld l, e
    call FAST_WRTVRM
    pop hl
    inc de
    ; Final digit: ones (remainder)
    ld a, l
    add a, '0'
    push hl
    ld h, d
    ld l, e
    call FAST_WRTVRM
    pop hl
    pop hl
    pop de
    pop bc
    pop af
    ret

; @mideas:endblock id=runtime.hud.core


; --- End of Far Bank 16 — pad to 8KB boundary ---
BANK_16_USED_END:
    ds #8000 - $, #FF
    org FAR_BANK_16_ROM_START + #2000

; ##################################################################
; FAR BANK 17 — [#6000h-#8000h] FAR CODE: font
; Accessed ONLY via trampolines in bank 0 (entrypoint_far labels).
; At runtime: bank0 saves P1, maps bank17 to P1,
; calls routine, then restores P1.
; NOTE: routines in this bank MUST only call code in bank 0 or
;       primary banks (1-2). No far-to-far calls allowed.
; ##################################################################
FAR_BANK_17_ROM_START:

    org #6000

; ==================================================================
; MSX FONT DATA FOR SCREEN 2 TEXT
; File: font.asm
; Description: Font pattern data generated from project assets
; ==================================================================

; FONT_DATA_ROM_DATA_GROUP: bank4
; (FONT_PATTERN_DATA and FONT_COLOR_DATA are in bank4 section, org #C000, for megarom builds)
FONT_PATTERN_DATA_BANK EQU ((FONT_PATTERN_DATA - #4000) / #2000)
FONT_COLOR_DATA_BANK   EQU ((FONT_COLOR_DATA - #4000) / #2000)

; ==================================================================
; FONT PATTERN DATA
; ==================================================================

FONT_PATTERN_DATA:
    ; Char 32 (' ')
    DB #00, #00, #00, #00, #00, #00, #00, #00
    ; Char 43 ('+')
    DB #00, #10, #10, #7C, #10, #10, #00, #00
    ; Char 44 (',')
    DB #00, #00, #00, #00, #08, #08, #08, #10
    ; Char 45 ('-')
    DB #00, #00, #00, #7E, #00, #00, #00, #00
    ; Char 46 ('.')
    DB #00, #00, #00, #00, #00, #18, #18, #00
    ; Char 48 ('0')
    DB #3E, #7F, #73, #73, #73, #7F, #3E, #00
    ; Char 49 ('1')
    DB #18, #38, #18, #18, #18, #18, #7E, #00
    ; Char 50 ('2')
    DB #3E, #7F, #03, #3E, #60, #7F, #3E, #00
    ; Char 51 ('3')
    DB #3E, #7F, #03, #3E, #03, #7F, #3E, #00
    ; Char 52 ('4')
    DB #06, #0E, #1E, #36, #7F, #06, #06, #00
    ; Char 53 ('5')
    DB #7F, #7F, #60, #7E, #03, #7F, #3E, #00
    ; Char 54 ('6')
    DB #3E, #7F, #60, #7E, #63, #7F, #3E, #00
    ; Char 55 ('7')
    DB #7F, #7F, #03, #06, #0C, #18, #18, #00
    ; Char 56 ('8')
    DB #3E, #7F, #63, #3E, #63, #7F, #3E, #00
    ; Char 57 ('9')
    DB #3E, #7F, #63, #3F, #03, #7F, #3E, #00
    ; Char 58 (':')
    DB #00, #36, #36, #00, #36, #36, #00, #00
    ; Char 62 ('>')
    DB #00, #30, #18, #0C, #18, #30, #00, #00
    ; Char 63 ('?')
    DB #3E, #7F, #63, #18, #18, #00, #18, #00
    ; Char 65 ('A')
    DB #3E, #7F, #63, #7F, #7F, #63, #63, #00
    ; Char 66 ('B')
    DB #7E, #7F, #63, #7E, #63, #7F, #7E, #00
    ; Char 67 ('C')
    DB #3C, #7E, #60, #60, #60, #7E, #3C, #00
    ; Char 68 ('D')
    DB #7C, #7E, #66, #66, #66, #7E, #7C, #00
    ; Char 69 ('E')
    DB #7F, #7F, #60, #7C, #60, #7F, #7F, #00
    ; Char 70 ('F')
    DB #7F, #7F, #60, #7C, #60, #60, #60, #00
    ; Char 71 ('G')
    DB #3E, #7F, #63, #60, #67, #7F, #3E, #00
    ; Char 72 ('H')
    DB #63, #63, #63, #7F, #63, #63, #63, #00
    ; Char 73 ('I')
    DB #3E, #3E, #1C, #1C, #1C, #3E, #3E, #00
    ; Char 74 ('J')
    DB #1F, #1F, #06, #06, #66, #7E, #3C, #00
    ; Char 75 ('K')
    DB #63, #66, #6C, #78, #6C, #66, #63, #00
    ; Char 76 ('L')
