    ; Char 46
    DB #F1, #F1, #F1, #F1, #F1, #F1, #F1, #F1
    ; Char 48
    DB #81, #81, #81, #91, #91, #91, #F1, #F1
    ; Char 49
    DB #81, #81, #81, #91, #91, #91, #F1, #F1
    ; Char 50
    DB #81, #81, #81, #91, #91, #91, #F1, #F1
    ; Char 51
    DB #81, #81, #81, #91, #91, #91, #F1, #F1
    ; Char 52
    DB #81, #81, #81, #91, #91, #91, #F1, #F1
    ; Char 53
    DB #81, #81, #81, #91, #91, #91, #F1, #F1
    ; Char 54
    DB #81, #81, #81, #91, #91, #91, #F1, #F1
    ; Char 55
