    ; Char 68
    DB #A1, #A1, #A1, #A1, #F1, #F1, #F1, #F1
    ; Char 69
    DB #A1, #A1, #A1, #A1, #F1, #F1, #F1, #F1
    ; Char 70
    DB #A1, #A1, #A1, #A1, #F1, #F1, #F1, #F1
    ; Char 71
    DB #A1, #A1, #A1, #A1, #F1, #F1, #F1, #F1
    ; Char 72
    DB #A1, #A1, #A1, #A1, #F1, #F1, #F1, #F1
